package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"testing"
)

// TestSynthTarIsLocalDifferential is a differential test of the vendored
// __tarIsLocal in the synthetic archive/tar source
// (synth_archive_tar.go, generated by gen_synth_archive_mime.py from gc
// 1.27.1) against gc's own path/filepath.IsLocal.
//
// Background (review finding SYN-11): the vendored copy used to reject any
// path containing a ".." element outright, while gc's
// internal/filepathlite.unixIsLocal Cleans such paths first and only
// rejects a cleaned path that still escapes (".." or "../..."). The
// divergence is observable when the insecure-path check is enforced
// (GODEBUG=tarinsecurepath=0, which makes tar.Reader.Next return
// ErrInsecurePath for non-local names): the old copy rejected entries like
// "a/../b" or "a/.." that gc accepts. The vendored function is now a
// faithful port of unixIsLocal; this test pins that parity.
//
// NOTE on the godebug stub: the synthetic tar stubs internal/godebug so
// tarinsecurepath.Value() is always "" (deliberate, documented); the
// vendored Next therefore never reports ErrInsecurePath in the default
// mode, exactly like gc's default mode. The probe below forces the
// enforcement mode (GODEBUG=tarinsecurepath=0) on the gc leg so the
// lexical difference under test is actually exercised.
//
// Method: the test extracts the __tarIsLocal function source from the
// committed generated artifact (failing loudly if it is absent or
// unparseable — drift detection), embeds it verbatim in a probe program,
// and runs the probe under the gc toolchain. The probe compares, for a
// matrix of tar entry names:
//  1. lexical level: __tarIsLocal(name) vs filepath.IsLocal(name);
//  2. archive level: for a real tar archive written by gc's tar.Writer and
//     read back by gc's tar.Reader under GODEBUG=tarinsecurepath=0,
//     whether Next() reports ErrInsecurePath matches the prediction
//     !__tarIsLocal(read-back name) — the exact guard shape gc uses
//     (err == nil && !IsLocal(name)).
// Positive controls pin the fixed semantics: filepath.IsLocal("a/../b")
// must be true (the old vendored copy returned false), and
// filepath.IsLocal("../esc") must be false (fail-closed direction kept).
func TestSynthTarIsLocalDifferential(t *testing.T) {
	fnSrc := extractVendoredTarIsLocal(t)

	scratchBase := filepath.Join(os.Getenv("HOME"), "workspace", "tmp-synth-tarlocal")
	if err := os.MkdirAll(scratchBase, 0o755); err != nil {
		t.Fatalf("mkdir scratch: %v", err)
	}
	probeDir, err := os.MkdirTemp(scratchBase, "islocal-probe-")
	if err != nil {
		t.Fatalf("mkdtemp: %v", err)
	}
	probePath := filepath.Join(probeDir, "main.go")
	if err := os.WriteFile(probePath, buildIsLocalProbe(fnSrc), 0o644); err != nil {
		t.Fatalf("write probe: %v", err)
	}

	goBin := filepath.Join(os.Getenv("HOME"), "tools", "go", "bin", "go")
	if _, err := os.Stat(goBin); err != nil {
		goBin = "go"
	}
	cmd := exec.Command(goBin, "run", probePath)
	cmd.Env = append(os.Environ(),
		"GOTOOLCHAIN=local",
		// Enforce gc's insecure-path check so the lexical difference
		// under test is observable on the gc leg (see note above).
		"GODEBUG=tarinsecurepath=0",
		"TMPDIR="+scratchBase,
		"GOTMPDIR="+scratchBase,
	)
	var out bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &out
	if err := cmd.Run(); err != nil {
		t.Fatalf("probe failed: %v\n%s", err, out.String())
	}
	t.Logf("probe output:\n%s", out.String())
	if strings.Contains(out.String(), "MISMATCH") || strings.Contains(out.String(), "FAIL") {
		t.Fatalf("differential mismatches found:\n%s", out.String())
	}
}

// extractVendoredTarIsLocal pulls the __tarIsLocal function source out of
// the committed generated artifact internal/frontend/synth_archive_tar.go.
// The tar sources live inside the syntheticArchiveTarSource string constant,
// so this unquotes the constant, re-parses it as Go, and renders the
// function. Any structural drift (constant renamed, function missing or
// unparseable) fails the test loudly.
func extractVendoredTarIsLocal(t *testing.T) string {
	t.Helper()
	_, thisFile, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("runtime.Caller failed")
	}
	genPath := filepath.Join(filepath.Dir(thisFile), "synth_archive_tar.go")
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, genPath, nil, 0)
	if err != nil {
		t.Fatalf("parse %s: %v", genPath, err)
	}
	var constLit *ast.BasicLit
	for _, decl := range f.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.CONST {
			continue
		}
		for _, spec := range gd.Specs {
			vs, ok := spec.(*ast.ValueSpec)
			if !ok || len(vs.Names) != 1 || vs.Names[0].Name != "syntheticArchiveTarSource" {
				continue
			}
			if len(vs.Values) != 1 {
				continue
			}
			if lit, ok := vs.Values[0].(*ast.BasicLit); ok && lit.Kind == token.STRING {
				constLit = lit
			}
		}
	}
	if constLit == nil {
		t.Fatal("syntheticArchiveTarSource constant not found in synth_archive_tar.go (drift?)")
	}
	tarSrc, err := strconv.Unquote(constLit.Value)
	if err != nil {
		t.Fatalf("unquote synthetic source: %v", err)
	}
	fset2 := token.NewFileSet()
	tf, err := parser.ParseFile(fset2, "synthetic_tar.go", tarSrc, 0)
	if err != nil {
		t.Fatalf("parse synthetic tar source: %v", err)
	}
	for _, decl := range tf.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Name.Name != "__tarIsLocal" || fd.Recv != nil {
			continue
		}
		var buf bytes.Buffer
		if err := format.Node(&buf, fset2, fd); err != nil {
			t.Fatalf("render __tarIsLocal: %v", err)
		}
		return buf.String()
	}
	t.Fatal("__tarIsLocal not found in syntheticArchiveTarSource (drift?)")
	return ""
}

// isLocalProbeNames is the differential matrix: dot-dot cases that gc
// accepts after Clean, absolute paths, escaping paths, and lexical edges.
var isLocalProbeNames = []string{
	"a/../b", "a/..", "a/./b", "./a", "a/.",
	"a/b", "a/b/c", "a/", "a//b",
	"", ".", "..", "../x", "a/../../x", "a/../..",
	"/abs/path", "/",
	"a/.../b", "...", "a/.../../b",
	"a/b/../c/d", "x/../y/../z",
}

func buildIsLocalProbe(tarIsLocalSrc string) []byte {
	var sb strings.Builder
	sb.WriteString(`package main

import (
	"archive/tar"
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path"
	"path/filepath"
	"strings"
)

`)
	sb.WriteString("// __tarIsLocal: extracted verbatim from the committed generated\n")
	sb.WriteString("// synthetic archive/tar source (see test).\n")
	sb.WriteString(tarIsLocalSrc)
	sb.WriteString(`

var probeNames = []string{
`)
	for _, n := range isLocalProbeNames {
		fmt.Fprintf(&sb, "\t%q,\n", n)
	}
	sb.WriteString(`}

func main() {
	failed := false
	// Positive controls: pin the semantics the SYN-11 fix restores.
	if !filepath.IsLocal("a/../b") {
		fmt.Println("FAIL: positive control: gc filepath.IsLocal(\"a/../b\") is false, test matrix invalid")
		failed = true
	}
	if filepath.IsLocal("../esc") {
		fmt.Println("FAIL: positive control: gc filepath.IsLocal(\"../esc\") is true, fail-closed direction broken")
		failed = true
	}
	if filepath.IsLocal("/abs") {
		fmt.Println("FAIL: positive control: gc filepath.IsLocal(\"/abs\") is true")
		failed = true
	}
	for _, name := range probeNames {
		// Level 1: lexical parity of the vendored function vs gc.
		got, want := __tarIsLocal(name), filepath.IsLocal(name)
		if got != want {
			fmt.Printf("MISMATCH lexical %q: vendored __tarIsLocal=%v, gc filepath.IsLocal=%v\n", name, got, want)
			failed = true
		}
		// Level 2: archive parity. Write a one-entry archive with gc's
		// tar.Writer, read it with gc's tar.Reader under
		// GODEBUG=tarinsecurepath=0 (enforcement mode), and check the
		// ErrInsecurePath verdict against the vendored prediction, using
		// the exact guard shape gc applies: a nil underlying read error
		// plus !IsLocal(hdr.Name) -> ErrInsecurePath. gc returns the
		// header together with ErrInsecurePath, so the read-back name is
		// available in both outcomes.
		var buf bytes.Buffer
		tw := tar.NewWriter(&buf)
		whErr := tw.WriteHeader(&tar.Header{Name: name, Mode: 0o644, Size: 0})
		cErr := tw.Close()
		if whErr != nil || cErr != nil {
			fmt.Printf("SKIP archive %q: writer error %v %v\n", name, whErr, cErr)
			continue
		}
		tr := tar.NewReader(&buf)
		hdr, rerr := tr.Next()
		if rerr == io.EOF || hdr == nil {
			fmt.Printf("SKIP archive %q: no entry read back (err=%v)\n", name, rerr)
			continue
		}
		if rerr != nil && !errors.Is(rerr, tar.ErrInsecurePath) {
			fmt.Printf("SKIP archive %q: unexpected reader error %v\n", name, rerr)
			continue
		}
		gcInsecure := errors.Is(rerr, tar.ErrInsecurePath)
		vendoredInsecure := !__tarIsLocal(hdr.Name)
		if gcInsecure != vendoredInsecure {
			fmt.Printf("MISMATCH archive %q (read back as %q): gc ErrInsecurePath=%v, vendored predicts=%v\n",
				name, hdr.Name, gcInsecure, vendoredInsecure)
			failed = true
		} else {
			fmt.Printf("ok %q -> readback %q insecure=%v\n", name, hdr.Name, gcInsecure)
		}
	}
	if failed {
		os.Exit(1)
	}
	fmt.Println("PROBE PASS")
}
`)
	return []byte(sb.String())
}
